input.oldString:
function draw() {
    ctx.clearRect(0, 0, width, height);
    // ship
    ctx.fillStyle = '#0af';
    ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
    // lasers
    ctx.fillStyle = '#f00';
    lasers.forEach(l => ctx.fillRect(l.x, l.y, l.w, l.h));
    // asteroids
    ctx.fillStyle = '#777';
    asteroids.forEach(a => ctx.beginPath(), ctx.arc(a.x + a.w/2, a.y + a.h/2, a.w/2, 0, Math.PI*2), ctx.fill());
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0,0,width,height);
      ctx.fillStyle = '#fff';
      ctx.font = '30px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width/2, height/2);
    }
  }

input.newString:
function draw() {
    // background gradient (deep space)
    const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
    bgGrad.addColorStop(0, '#001');
    bgGrad.addColorStop(1, '#000');
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // starfield
    ctx.fillStyle = '#fff';
    stars.forEach(s => {
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
      ctx.fill();
    });

    // ship – drawn as triangle (already modified)
    // ship drawing code remains unchanged

    // lasers – glow effect
    lasers.forEach(l => {
      const grad = ctx.createLinearGradient(0, l.y + l.h, 0, l.y);
      grad.addColorStop(0, 'rgba(255,0,0,0)');
      grad.addColorStop(1, '#f00');
      ctx.fillStyle = grad;
      ctx.fillRect(l.x, l.y, l.w, l.h);
    });

    // asteroids – radial gradient for a rocky look
    asteroids.forEach(a => {
      const radGrad = ctx.createRadialGradient(
        a.x + a.w / 2,
        a.y + a.h / 2,
        a.w * 0.2,
        a.x + a.w / 2,
        a.y + a.h / 2,
        a.w / 2
      );
      radGrad.addColorStop(0, '#bbb');
      radGrad.addColorStop(1, '#555');
      ctx.fillStyle = radGrad;
      ctx.beginPath();
      ctx.arc(a.x + a.w / 2, a.y + a.h / 2, a.w / 2, 0, Math.PI * 2);
      ctx.fill();
    });

    // ship – triangle (original code moved earlier, keep original call)
    ctx.fillStyle = '#0af';
    ctx.beginPath();
    ctx.moveTo(ship.x, ship.y + ship.h);
    ctx.lineTo(ship.x + ship.w / 2, ship.y);
    ctx.lineTo(ship.x + ship.w, ship.y + ship.h);
    ctx.closePath();
    ctx.fill();

    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0,0,width,height);
      ctx.fillStyle = '#fff';
      ctx.font = '30px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width/2, height/2);
    }
  }

